const input = $input.first().json.body || $input.first().json;

const income = Number(input.income || 60000);
const expenses = Number(input.expenses || 35000);
const commitments = Number(input.mandatoryCommitments || 5000);
const emergencyFund = Number(input.emergencyFund || 100000);

const surplus = Math.max(0, income - expenses - commitments);
const monthlyBufferNeeds = expenses + commitments;
const emergencyMonths = monthlyBufferNeeds > 0 ? (emergencyFund / monthlyBufferNeeds) : 0;

// Investment Capacity Logic
let factorMin = emergencyMonths < 3 ? 0.40 : 0.50;
let factorMax = emergencyMonths < 3 ? 0.70 : 0.80;

const capacityMin = Math.round(surplus * factorMin);
const capacityMax = Math.round(surplus * factorMax);

return {
  json: {
    userId: input.userId,
    financialSummary: {
      monthlyIncome: income,
      monthlyExpenses: expenses,
      mandatoryCommitments: commitments,
      monthlySurplus: surplus,
      emergencyFundMonths: Number(emergencyMonths.toFixed(1))
    },
    estimatedInvestmentCapacity: {
      min: capacityMin,
      max: capacityMax,
      recommendedMonthlyTarget: Math.round((capacityMin + capacityMax) / 2),
      label: 'Estimated Investment Capacity'
    },
    riskProfile: input.riskProfile || 'Moderate',
    operation: input.operation || 'PROFILE_SUMMARY'
  }
};
